algorithms.pseudocode:
check(subject, perm, resource, ctx, minRev):
  if minRev and graph.applied < minRev:
     if not graph.waitFor(minRev, 50ms): return forwardToFreshReplica()
  chain = scopeChain(resource)          # order:987 -> seller:s7 -> global
  principals = [subject] + flatGroups[subject]
  for scope in chain:
    for p in principals:
      for role in subjectRoles[(p, scope)]:
        if role.expired(now): continue
        if rolePerms[role].has(perm):
          if role.condition is None or eval(role.condition, ctx):
             return ALLOW(role, scope, graph.applied)
  return DENY('no matching grant', graph.applied)

loop:
  batch = kafka.poll(max=500)
  for tenant, changes in groupBy(batch, tenant):
     seg = graph.segment(tenant).clone()
     for c in sorted(changes, key=(revision)):
        if c.op == DELETE: seg.remove(c.tuple)
        else: seg.add(c.tuple)
     graph.swap(tenant, seg)            # atomic pointer swap
  graph.applied = max(revision in batch)
  commit offsets
